package com.bautruc.ecommerce.chat.api;
import java.time.Duration;
import com.bautruc.ecommerce.chat.api.request.ChatMessageRequest;import com.bautruc.ecommerce.chat.application.ChatService;import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.ApiResponse;import com.bautruc.ecommerce.common.time.BusinessClock;import jakarta.servlet.http.HttpServletResponse;import jakarta.validation.Valid;import org.springframework.core.env.Environment;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/chat") public class ChatController { private static final String COOKIE_NAME="BT_CHAT"; private final ChatService chat;private final BusinessClock clock;private final Environment environment; public ChatController(ChatService chat,BusinessClock clock,Environment environment){this.chat=chat;this.clock=clock;this.environment=environment;} @GetMapping("/session") public ApiResponse<ChatService.ThreadView> session(@CookieValue(value=COOKIE_NAME,required=false)String cookie,HttpServletResponse response){noStore(response);return ok(chat.mine(cookie));} @PostMapping("/messages") public ApiResponse<ChatService.ThreadView> send(@CookieValue(value=COOKIE_NAME,required=false)String cookie,@Valid @RequestBody ChatMessageRequest request,HttpServletResponse response){noStore(response);var result=chat.send(cookie,request);if(result.newGuestToken()!=null)response.addHeader(HttpHeaders.SET_COOKIE,ResponseCookie.from(COOKIE_NAME,result.newGuestToken()).httpOnly(true).secure(environment.matchesProfiles("prod")).sameSite("Lax").path("/").maxAge(Duration.ofDays(60)).build().toString());return ok(result.thread());} @PatchMapping("/close") public ApiResponse<ChatService.ThreadView> close(@CookieValue(value=COOKIE_NAME,required=false)String cookie,HttpServletResponse response){noStore(response);return ok(chat.closeMine(cookie));} private void noStore(HttpServletResponse response){response.setHeader("Cache-Control","no-store");} private <T>ApiResponse<T> ok(T data){return ApiResponse.success(data,null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
